import {getAction} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand} from './scenario-tools.js';
export const leafDefenseScenarios=['leaf-ordinary','leaf-dedicated','leaf-three-ordinary','leaf-three-dedicated'] as const;
export type LeafDefenseScenario=typeof leafDefenseScenarios[number];
export function isLeafDefenseScenario(name:string):name is LeafDefenseScenario{return (leafDefenseScenarios as readonly string[]).includes(name);}
export function leafDefenseMode(name:LeafDefenseScenario){return {dedicated:name.endsWith('dedicated'),three:name.includes('-three-'),card:'a2-p13-r2c2'};}
export function makeLeafDefenseScenario(name:LeafDefenseScenario,players:{id:string;name:string}[],options:{level?:number;owner?:string;attack?:'fire'|'wind'|'warrior'|'prohibited';bonus?:number;beforeAttack?:boolean}={}){
 const m=leafDefenseMode(name);let s=createGame(players,entropy(),{startingSeat:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];assignCharacter(s,a,options.attack==='prohibited'?'吟遊詩人のレスター':'侍大将のシン');assignCharacter(s,b,options.owner??'忍びのイダ');assignCharacter(s,c,'大神官ジル');assignCharacter(s,d,'魔導王ガイナス');for(const p of Object.values(s.players))p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};s.players[b]!.permanent!.magic_level=20+(options.level??3)-gameStats(s,b).magic_level;s.players[a]!.permanent!.spirit=20+6-gameStats(s,a).spirit;s.players[b]!.permanent!.spirit=20+6-gameStats(s,b).spirit;
 const attack=takeCard(s,a,m.three?'天地百撃斬':options.attack==='fire'?'炎矢':options.attack==='wind'?'風矢':options.attack==='warrior'?'黒翼飛翔剣':options.attack==='prohibited'?'呪歌':'衝破'),card=takeCard(s,b,m.card),evade=takeCard(s,b,'a2-p05-r3c1'),fate=takeCard(s,c,'命運凶変'),prayer=options.bonus?takeCard(s,a,'必勝の祈り'):null;for(const id of [a,b,c,d])trimHand(s,id,attack,card,evade,fate,...(prayer?[prayer]:[]));s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];
 function act(actorId:string,command:GameCommand){const input={actorId,command},e={...entropy(),dice:Array(100).fill(options.bonus??(m.three?3:1))},r=transition(s,input,e);if(!r.ok)throw Error(`LEAF_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('LEAF_JSON');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('LEAF_IDS');}
 for(const id of [a,b,c,d])act(id,{type:'PASS_SETUP'});act(a,{type:'START_TURN'});act(a,{type:'CHOOSE_DRAW',draw:false});if(m.three){act(a,{type:'CHANT',cardInstanceId:attack});for(let n=0;n<180;n++){const id=s.seatOrder[s.turnSeat]!,w=s.windows?.at(-1);if(w)act(w.participants[w.cursor]!,{type:'PASS'});else if(s.phase==='action'){if(id===a)break;act(id,{type:'PASS_ACTION'});}else if(s.phase==='withdrawal')act(id,{type:'PASS_WITHDRAWAL'});else if(s.phase==='hand-adjustment')act(id,{type:'END_TURN',discardIds:s.players[id]!.hand.slice(0,Math.max(0,s.players[id]!.hand.length-gameStats(s,id).handLimit))});else if(s.phase==='turn-start')act(id,{type:'START_TURN'});else if(s.phase==='draw')act(id,{type:'CHOOSE_DRAW',draw:false});else throw Error('LEAF_TURN');}}
 if(options.beforeAttack)return s;act(a,{type:'ATTACK',cardInstanceId:attack,targetIds:m.three?[b,c]:[b],dedicated:m.three||options.attack==='prohibited'});let boosted=false;for(let n=0;n<300;n++){const w=s.windows!.at(-1)!;if(w.kind==='normal-defense')return s;if(prayer&&!boosted&&w.kind==='effect-level'){act(a,{type:'PLAY_REACTION',cardInstanceId:prayer,mode:'effect-plus',targetActionId:w.continuation.id});boosted=true;}else act(w.participants[w.cursor]!,{type:'PASS'});}throw Error('LEAF_WINDOW');
}
